def ket(dim, args):
    '''Input:
    dim: int or list, dimension of the ket
    args: int or list, the i-th basis vector
    Output:
    out: dim dimensional array of float, the matrix representation of the ket
    '''

    def get_single_ket(d, j):
        v = np.zeros(d)
        v[j] = 1.0
        return v

    if isinstance(dim, int):
        # Case 1: dim is int, args is list [j1, j2, ..., jn]
        # Return tensor product of d-dimensional basis vectors
        res = None
        for j in args:
            v = get_single_ket(dim, j)
            if res is None:
                res = v
            else:
                res = np.kron(res, v)
        out = res
    elif isinstance(dim, list):
        # Case 2: dim is list [d1, d2, ..., dn], args is list [j1, j2, ..., jn]
        # Return tensor product of di-dimensional basis vectors
        res = None
        for d, j in zip(dim, args):
            v = get_single_ket(d, j)
            if res is None:
                res = v
            else:
                res = np.kron(res, v)
        out = res
    else:
        # Fallback for simple single vector case if dim is int and args is int
        if isinstance(args, int):
            out = get_single_ket(dim, args)
        else:
            raise ValueError("Invalid input types for dim and args")

    return out
